-- failure, so they expect every role; the write probes expect none. All
-- fixture rows are invented (ids 9e030000-...).
--
-- Run: npx supabase db reset && ./scripts/seed-local-dev-staff.sh
--      ./scripts/role-matrix.sh supabase/role-matrix/20261011100000_admissions_core_applicants_structure.sql

