-- ================================================================ grants

-- probe: A1 anon has no privilege on any table; authenticated has select only
-- expect: anon,Attendant,Manager,Accountant,Auditor,Admissions Officer
do $$
declare t text;
begin
  foreach t in array array['public.families', 'public.guardians', 'public.students', 'public.applications', 'public.application_emergency_contacts', 'public.application_notes'] loop
    if has_table_privilege('anon', t, 'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER') then
      raise exception 'anon holds a privilege on %', t;
    end if;
    if not has_table_privilege('authenticated', t, 'SELECT')
       or has_table_privilege('authenticated', t, 'INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER') then
      raise exception 'authenticated privileges wrong on %', t;
    end if;
    if not (select relrowsecurity from pg_class where oid = t::regclass) then
      raise exception 'RLS off on %', t;
    end if;
    if exists (select 1 from pg_policies where schemaname || '.' || tablename = t and cmd <> 'SELECT') then
      raise exception 'a non-select policy exists on %', t;
    end if;
  end loop;
end $$;

-- probe: A2 no new function is executable by anon; trigger functions by nobody signed in
-- expect: anon,Attendant,Manager,Accountant,Auditor,Admissions Officer
do $$ begin
  if has_function_privilege('anon', 'public.admissions_application_visible(uuid)', 'execute')
     or has_function_privilege('anon', 'public.admissions_student_visible(uuid)', 'execute')
     or has_function_privilege('anon', 'public.admissions_family_visible(uuid)', 'execute')
     or has_function_privilege('anon', 'public.normalise_guardian_email()', 'execute')
     or has_function_privilege('authenticated', 'public.normalise_guardian_email()', 'execute')
     or has_function_privilege('anon', 'public.set_application_note_identity()', 'execute')
     or has_function_privilege('authenticated', 'public.set_application_note_identity()', 'execute') then
    raise exception 'unexpected execute privilege';
  end if;
end $$;

-- probe: A3 the visibility helpers are security definer with search_path pinned
-- expect: anon,Attendant,Manager,Accountant,Auditor,Admissions Officer
do $$ begin
  if exists (
    select 1 from pg_proc
    where oid in ('public.admissions_application_visible(uuid)'::regprocedure,
                  'public.admissions_student_visible(uuid)'::regprocedure,
                  'public.admissions_family_visible(uuid)'::regprocedure)
      and (not prosecdef or not coalesce('search_path=public' = any (proconfig), false))
  ) then
    raise exception 'a helper lost security definer or its search_path';
  end if;
end $$;

