-- probe: C3 refused: duplicate references, student ids and unsubscribe hashes
-- expect: anon,Attendant,Manager,Accountant,Auditor,Admissions Officer
update public.applications set inquiry_reference = 'INQ-2026-0001' where id = '9e030000-0000-4000-8000-000400000001';
update public.students set student_id = '26030001' where id = '9e030000-0000-4000-8000-000300000001';
update public.guardians set bulk_email_unsubscribe_token_hash = repeat('a', 64) where id = '9e030000-0000-4000-8000-000200000001';
do $$ begin
  update public.applications set inquiry_reference = 'INQ-2026-0001' where id = '9e030000-0000-4000-8000-000400000002';
  raise exception 'duplicate reference accepted';
exception when unique_violation then null; end $$;
do $$ begin
  update public.students set student_id = '26030001' where id = '9e030000-0000-4000-8000-000300000002';
  raise exception 'duplicate student id accepted';
exception when unique_violation then null; end $$;
do $$ begin
  update public.guardians set bulk_email_unsubscribe_token_hash = repeat('a', 64) where id = '9e030000-0000-4000-8000-000200000002';
  raise exception 'duplicate hash accepted';
exception when unique_violation then null; end $$;
-- as role:
select 1;

-- probe: C4 deleting a family cascades to everything under it
-- expect: anon,Attendant,Manager,Accountant,Auditor,Admissions Officer
delete from public.families where id = '9e030000-0000-4000-8000-000100000002';
do $$ begin
  if exists (select 1 from public.guardians where family_id = '9e030000-0000-4000-8000-000100000002')
     or exists (select 1 from public.students where id = '9e030000-0000-4000-8000-000300000004')
     or exists (select 1 from public.applications where id = '9e030000-0000-4000-8000-000400000004')
     or exists (select 1 from public.application_emergency_contacts where id = '9e030000-0000-4000-8000-000500000001')
     or exists (select 1 from public.application_notes where id = '9e030000-0000-4000-8000-000600000001') then
    raise exception 'cascade incomplete';
  end if;
end $$;
-- as role:
select 1;

-- ================================================================ triggers

-- probe: R1 guardian email is lowercased and trimmed
-- expect: anon,Attendant,Manager,Accountant,Auditor,Admissions Officer
update public.guardians set email = '  Esi.Fixture@Example.TEST ' where id = '9e030000-0000-4000-8000-000200000003';
do $$ begin
  if (select email from public.guardians where id = '9e030000-0000-4000-8000-000200000003') <> 'esi.fixture@example.test' then
    raise exception 'email not normalised';
  end if;
end $$;
-- as role:
select 1;

-- probe: R2 a signed-in writer's note gets their id and the current time
-- expect: anon,Attendant,Manager,Accountant,Auditor,Admissions Officer
select set_config('request.jwt.claims', json_build_object('sub', (select id from public.staff where role = 'Manager' and active order by id limit 1))::text, true);
  values ('9e030000-0000-4000-8000-000600000002', '9e030000-0000-4000-8000-000400000004', null, 'x', '2020-01-01');
select set_config('request.jwt.claims', '', true);
do $$ begin
  if (select author_id from public.application_notes where id = '9e030000-0000-4000-8000-000600000002') is distinct from (select id from public.staff where role = 'Manager' and active order by id limit 1)
     or (select created_at from public.application_notes where id = '9e030000-0000-4000-8000-000600000002') < now() - interval '1 minute' then
    raise exception 'identity not forced';
  end if;
end $$;
-- as role:
select 1;

-- ================================================================ import shape (slice 15)

-- probe: I1 a legacy-shaped record keeps its ids, timestamps, references and authorless note
-- expect: anon,Attendant,Manager,Accountant,Auditor,Admissions Officer

  values ('9e030000-0000-4000-8000-000200000014', '9e030000-0000-4000-8000-000100000014', 'Legacy@Example.test', '+233200000020', 'mother', repeat('b', 64));
    application_reference, branch_id, declaration_agreed, declaration_agreed_at, created_at, updated_at)
  values ('9e030000-0000-4000-8000-000400000014', '9e030000-0000-4000-8000-000300000014', 'enrolled', '2026/2027', 'KG2', 'INQ-2026-0003', 'APP-2026-0002',
    (select id from public.branches order by created_at offset 1 limit 1), true, '2026-09-04 09:00+00',
    '2026-09-03 10:00+00', '2026-09-05 12:00+00');
  values ('9e030000-0000-4000-8000-000600000014', '9e030000-0000-4000-8000-000400000014', 'Legacy note', '2026-09-04 08:00+00');
do $$ begin
  if (select created_at from public.families where id = '9e030000-0000-4000-8000-000100000014') <> '2026-09-03 10:00+00'
     or (select (created_at, updated_at) from public.applications where id = '9e030000-0000-4000-8000-000400000014')
        is distinct from ('2026-09-03 10:00+00'::timestamptz, '2026-09-05 12:00+00'::timestamptz)
     or (select (author_id, created_at) from public.application_notes where id = '9e030000-0000-4000-8000-000600000014')
        is distinct from (null::uuid, '2026-09-04 08:00+00'::timestamptz)
     or (select student_id from public.students where id = '9e030000-0000-4000-8000-000300000014') <> '26030003'
     or (select email from public.guardians where id = '9e030000-0000-4000-8000-000200000014') <> 'legacy@example.test'
     or (select branch_id from public.applications where id = '9e030000-0000-4000-8000-000400000014') is null then
    raise exception 'legacy values not preserved';
  end if;
end $$;
-- as role:
select 1;
